  1	/**
  2	 * Error Log View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders a paginated, filterable table of error log entries fetched from the
  5	 * REST API:
  6	 *   - Severity and source filter dropdowns re-fetch entries on change.
  7	 *   - Clicking a row toggles an inline `<pre>` detail panel below it.
  8	 *   - "Clear All" button prompts a confirmation dialog and clears all entries.
  9	 *   - Timestamps display relative time (e.g. "3 min ago") with the full ISO
 10	 *     timestamp in the `title` tooltip.
 11	 *   - Severity is rendered as a coloured badge using `.severity-error` or
 12	 *     `.severity-warning` CSS classes.
 13	 *   - All dynamic text is set via `textContent` (never `innerHTML`) for XSS
 14	 *     safety.
 15	 *
 16	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 17	 * @param {Object}      _params   - Route params (none for this route).
 18	 */
 19	
 20	import { api }          from '../api.js';
 21	import { showToast }    from '../components/toast.js';
 22	import { showConfirm }  from '../components/confirm-dialog.js';
 23	import { normaliseErrorEntry } from '../utils/normalise.js';
 24	import { relativeTime } from '../utils/time.js';
 25	import { refreshNavBadge } from '../components/nav-badge.js';
 26	import { APP_NAME_SHORT } from '../utils/constants.js';
 27	
 28	// ---------------------------------------------------------------------------
 29	// Severity options — kept in one place so filters and dropdowns stay in sync.
 30	// ---------------------------------------------------------------------------
 31	
 32	const SEVERITY_OPTIONS = [
 33	    { value: 'all',     label: 'All Severities' },
 34	    { value: 'error',   label: 'Error'          },
 35	    { value: 'warning', label: 'Warning'        },
 36	    { value: 'audit',   label: 'Audit'          },
 37	    { value: 'info',    label: 'Info'           },
 38	];
 39	
 40	// ---------------------------------------------------------------------------
 41	// Context breadcrumb helper
 42	// ---------------------------------------------------------------------------
 43	
 44	/**
 45	 * Build a compact breadcrumb string from project / workspace / repository fields.
 46	 *
 47	 * @param {{ project: string, workspace: string, repository: string }} entry
 48	 * @returns {string}
 49	 */
 50	function buildContextBreadcrumb(entry) {
 51	    return [entry.project, entry.workspace, entry.repository]
 52	        .filter(Boolean)
 53	        .join(' / ') || '—';
 54	}
 55	
 56	// ---------------------------------------------------------------------------
 57	// Filter bar
 58	// ---------------------------------------------------------------------------
 59	
 60	/**
 61	 * Build the filter bar containing the severity and source dropdowns plus the
 62	 * "Clear All" button.
 63	 *
 64	 * @param {{ severity: string, source: string }} currentFilters
 65	 * @param {Array<{ value: string, label: string }>} sourceOptions
 66	 * @param {function({ severity: string, source: string }): void} onFilterChange
 67	 * @param {function(): void} onClearAll
 68	 * @returns {HTMLElement}
 69	 */
 70	function buildFilterBar(currentFilters, sourceOptions, onFilterChange, onClearAll) {
 71	    const bar = document.createElement('div');
 72	    bar.className = 'error-log-filter-bar';
 73	
 74	    // ---- Severity dropdown ----
 75	    const severityLabel = document.createElement('label');
 76	    severityLabel.textContent = 'Severity:';
 77	    severityLabel.setAttribute('for', 'error-log-severity-filter');
 78	    severityLabel.className = 'filter-label';
 79	
 80	    const severitySelect = document.createElement('select');
 81	    severitySelect.id        = 'error-log-severity-filter';
 82	    severitySelect.className = 'form-select';
 83	
 84	    SEVERITY_OPTIONS.forEach(({ value, label }) => {
 85	        const opt = document.createElement('option');
 86	        opt.value       = value;
 87	        opt.textContent = label;
 88	        opt.selected    = value === currentFilters.severity;
 89	        severitySelect.appendChild(opt);
 90	    });
 91	
 92	    // ---- Source dropdown ----
 93	    const sourceLabel = document.createElement('label');
 94	    sourceLabel.textContent = 'Source:';
 95	    sourceLabel.setAttribute('for', 'error-log-source-filter');
 96	    sourceLabel.className = 'filter-label';
 97	
 98	    const sourceSelect = document.createElement('select');
 99	    sourceSelect.id        = 'error-log-source-filter';
100	    sourceSelect.className = 'form-select';

  1	/**
  2	 * Unit tests for views/error-log.js — WP-006.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1  — SEVERITY_OPTIONS includes { value: 'audit', label: 'Audit' }.
  6	 *   AC2  — SEVERITY_OPTIONS includes { value: 'info', label: 'Info' }.
  7	 *   AC3  — The severity filter dropdown rendered by renderErrorLog contains
  8	 *           an "Audit" option and an "Info" option.
  9	 *
 10	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 11	 * Run individually with:
 12	 *   node --test gui/public/js/views/error-log.test.mjs
 13	 */
 14	
 15	import { test } from 'node:test';
 16	import assert from 'node:assert/strict';
 17	import { JSDOM } from 'jsdom';
 18	
 19	// ---------------------------------------------------------------------------
 20	// jsdom setup — install globals before any module is imported
 21	// ---------------------------------------------------------------------------
 22	
 23	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="toast-container"></div></body></html>', {
 24	    url: 'http://localhost/',
 25	});
 26	
 27	const { window } = dom;
 28	
 29	globalThis.document    = window.document;
 30	globalThis.window      = window;
 31	globalThis.location    = window.location;
 32	globalThis.HTMLElement = window.HTMLElement;
 33	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/[!"#$%&'()*+,./:;<=>?@[\\\]^`{|}~]/g, '\\$&') };
 34	
 35	// ---------------------------------------------------------------------------
 36	// Minimal fetch mock (required by api.js)
 37	// ---------------------------------------------------------------------------
 38	
 39	globalThis.fetch = async () => ({
 40	    status: 200,
 41	    ok: true,
 42	    statusText: 'OK',
 43	    headers: { get: () => 'application/json' },
 44	    json: async () => ({ entries: [], total: 0, sources: [] }),
 45	});
 46	
 47	// ---------------------------------------------------------------------------
 48	// Import API and set up mocks
 49	// ---------------------------------------------------------------------------
 50	
 51	const { api } = await import('../api.js');
 52	
 53	api.errorLog = {
 54	    list:    async () => ({ entries: [], total: 0 }),
 55	    sources: async () => ({ sources: [] }),
 56	    clear:   async () => ({}),
 57	};
 58	
 59	// ---------------------------------------------------------------------------
 60	// Import module under test
 61	// ---------------------------------------------------------------------------
 62	
 63	const { renderErrorLog } = await import('./error-log.js');
 64	
 65	// ---------------------------------------------------------------------------
 66	// Helpers
 67	// ---------------------------------------------------------------------------
 68	
 69	/**
 70	 * Render the Error Log view into a fresh container and wait for async
 71	 * bootstrap (API fetch + DOM construction).
 72	 *
 73	 * @returns {Promise<HTMLElement>} The outermost container element.
 74	 */
 75	async function renderAndWait() {
 76	    const container = document.createElement('div');
 77	    container.id = 'app';
 78	    document.body.appendChild(container);
 79	
 80	    await renderErrorLog(container, {});
 81	
 82	    // Flush any remaining micro-tasks.
 83	    await new Promise((resolve) => setTimeout(resolve, 0));
 84	
 85	    return container;
 86	}
 87	
 88	/**
 89	 * Remove all rendered containers after each test.
 90	 */
 91	function cleanupContainers() {
 92	    document.body.querySelectorAll('#app').forEach((el) => el.remove());
 93	}
 94	
 95	// ---------------------------------------------------------------------------
 96	// Tests
 97	// ---------------------------------------------------------------------------
 98	
 99	test('AC1 — severity filter dropdown contains an "Audit" option', async () => {
100	    const container = await renderAndWait();

101	
102	    sourceOptions.forEach(({ value, label }) => {
103	        const opt = document.createElement('option');
104	        opt.value       = value;
105	        opt.textContent = label;
106	        opt.selected    = value === currentFilters.source;
107	        sourceSelect.appendChild(opt);
108	    });
109	    // ---- Clear All button ----
110	    const clearBtn = document.createElement('button');
111	    clearBtn.type      = 'button';
112	    clearBtn.className = 'btn btn-danger';
113	    clearBtn.textContent = 'Clear All';
114	
115	    // ---- Event wiring ----
116	    function emitFilterChange() {
117	        onFilterChange({
118	            severity: severitySelect.value,
119	            source:   sourceSelect.value,
120	        });
121	    }
122	
123	    severitySelect.addEventListener('change', emitFilterChange);
124	    sourceSelect.addEventListener('change', emitFilterChange);
125	    clearBtn.addEventListener('click', onClearAll);
126	
127	    // ---- Assemble ----
128	    bar.appendChild(severityLabel);
129	    bar.appendChild(severitySelect);
130	    bar.appendChild(sourceLabel);
131	    bar.appendChild(sourceSelect);
132	    bar.appendChild(clearBtn);
133	
134	    return bar;
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Table building
139	// ---------------------------------------------------------------------------
140	
141	/**
142	 * Build the `<thead>` element for the error log table.
143	 *
144	 * @returns {HTMLTableSectionElement}
145	 */
146	function buildTableHead() {
147	    const thead = document.createElement('thead');
148	    const tr    = document.createElement('tr');
149	
150	    ['Timestamp', 'Severity', 'Source', 'Context', 'Message'].forEach((label) => {
151	        const th = document.createElement('th');
152	        th.textContent = label;
153	        tr.appendChild(th);
154	    });
155	
156	    thead.appendChild(tr);
157	    return thead;
158	}
159	
160	/**
161	 * Build a severity badge `<span>` for the given severity string.
162	 *
163	 * @param {string} severity - 'error', 'warning', or any other string.
164	 * @returns {HTMLSpanElement}
165	 */
166	function buildSeverityBadge(severity) {
167	    const badge = document.createElement('span');
168	    const normalised = severity ? severity.toLowerCase() : '';
169	    badge.className = normalised
170	        ? `severity-badge severity-${normalised}`
171	        : 'severity-badge';
172	    badge.textContent = severity || '—';
173	    return badge;
174	}
175	
176	/**
177	 * Build a table row pair: the main data row and a hidden detail row below it.
178	 *
179	 * Clicking the main row toggles the visibility of the detail row.
180	 *
181	 * @param {Object} rawEntry - Raw entry object from the API response.
182	 * @returns {DocumentFragment} A fragment containing the data row and the
183	 *   (initially hidden) detail row.
184	 */
185	function buildEntryRows(rawEntry) {
186	    const entry = normaliseErrorEntry(rawEntry);
187	    const frag  = document.createDocumentFragment();
188	
189	    // ---- Main data row ----
190	    const tr = document.createElement('tr');
191	    tr.className = 'error-log-entry-row';
192	    tr.setAttribute('role', 'button');
193	    tr.setAttribute('tabindex', '0');
194	    tr.setAttribute('aria-expanded', 'false');
195	
196	    // Timestamp cell
197	    const tsCell = document.createElement('td');
198	    tsCell.className = 'error-log-ts-cell';
199	    const tsSpan = document.createElement('span');
200	    tsSpan.textContent = relativeTime(entry.timestamp);
201	    tsSpan.title       = entry.timestamp;
202	    tsCell.appendChild(tsSpan);
203	    tr.appendChild(tsCell);
204	
205	    // Severity cell
206	    const severityCell = document.createElement('td');
207	    severityCell.className = 'error-log-severity-cell';
208	    severityCell.appendChild(buildSeverityBadge(entry.severity));
209	    tr.appendChild(severityCell);
210	
211	    // Source cell
212	    const sourceCell = document.createElement('td');
213	    sourceCell.className = 'error-log-source-cell';
214	    sourceCell.textContent = entry.source || '—';
215	    tr.appendChild(sourceCell);
216	
217	    // Context cell
218	    const contextCell = document.createElement('td');
219	    contextCell.className = 'error-log-context-cell text-muted';
220	    contextCell.textContent = buildContextBreadcrumb(entry);
221	    tr.appendChild(contextCell);
222	
223	    // Message cell
224	    const msgCell = document.createElement('td');
225	    msgCell.className = 'error-log-message-cell';
226	    msgCell.textContent = entry.message || '—';
227	    tr.appendChild(msgCell);
228	
229	    // ---- Detail row (hidden by default) ----
230	    const detailTr = document.createElement('tr');
231	    detailTr.className = 'error-log-detail-row';
232	    detailTr.hidden    = true;
233	
234	    const detailTd = document.createElement('td');
235	    detailTd.colSpan = 5;
236	
